  <script src="https://cdn.jsdelivr.net/npm/expr-eval@2/dist/bundle.min.js"></script>

  <style>
    /* ── Reset ───────────────────────────────────────────────────────────── */
    html,
    body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #fff;
    }

    /* ── Layout ──────────────────────────────────────────────────────────────
       body is a grid so #ui always takes a right-side column instead of covering
       the figure. The #container ResizeObserver then fires 'fig-resize', so
       setPlotFrame re-lays the figure out at its new size automatically.        */
    body {
      display: grid;
      grid-template-columns: 1fr;
      grid-template-rows: 1fr;
      grid-template-areas: "stage";
    }

    /* ── Figure mount point ──────────────────────────────────────────────── */
    #container {
      position: relative;
      grid-area: stage;
      min-width: 0;
      min-height: 0;
      overflow: hidden;
      box-sizing: border-box;
      padding: var(--figure-canvas-padding, 18px);
    }

    /* ── Control panel (mirrors base_scene_new.html #ui) ─────────────────── */
    #ui {
      position: absolute;
      left: 6px;
      bottom: 6px;
      display: flex;
      flex-direction: column;
      gap: 3px;
      font-family: sans-serif;
      font-size: 11px;
      max-width: 190px;
      max-height: 34%;
      overflow-y: auto;
      overflow-x: hidden;
      background: transparent;
      border: 0;
      box-shadow: none;
      opacity: 0.88;
      transform: none;
      transition: opacity 0.16s ease;
      z-index: 10;
    }

    #ui:hover,
    #ui:focus-within {
      opacity: 1;
    }

    #ui button {
      padding: 4px 10px;
      cursor: pointer;
      border: 1px solid #aaa;
      background: #f5f5f5;
      border-radius: 4px;
    }

    #ui button:hover {
      background: #e0e0e0;
    }

    #ui button.active {
      background: #c8e6ff;
      border-color: #5aabf0;
    }

    #ui label {
      display: flex;
      flex-direction: column;
      gap: 2px;
      text-shadow: 0 1px 2px #fff;
    }

    #ui input[type=range] {
      width: 86px;
    }

    /* ── Docked control panel ────────────────────────────────────────────────
       #ui is a grid cell with its own scroll, an opaque background, and roomier
       type. Generated code cannot switch it to an overlay or bottom strip.      */
    body[data-ui-layout="right"] {
      grid-template-columns: 1fr var(--ui-size, 320px);
      grid-template-rows: 1fr;
      grid-template-areas: "stage ui";
    }

    body[data-ui-layout="bottom"] {
      grid-template-columns: 1fr;
      grid-template-rows: 1fr var(--ui-size, 240px);
      grid-template-areas: "stage" "ui";
    }

    body[data-ui-layout="right"] #ui,
    body[data-ui-layout="bottom"] #ui {
      position: relative;
      grid-area: ui;
      left: auto;
      bottom: auto;
      max-width: none;
      max-height: none;
      min-width: 0;
      min-height: 0;
      width: auto;
      height: auto;
      gap: 6px;
      padding: 10px 12px;
      font-size: 12px;
      background: #fbfbfc;
      opacity: 1;
      overflow: auto;
      z-index: 1;
    }

    body[data-ui-layout="right"] #ui {
      border-left: 1px solid #dcdfe3;
    }

    body[data-ui-layout="bottom"] #ui {
      border-top: 1px solid #dcdfe3;
    }

    body[data-ui-layout="right"] #ui label,
    body[data-ui-layout="bottom"] #ui label {
      text-shadow: none;
    }

    body[data-ui-layout="right"] #ui input[type=range],
    body[data-ui-layout="bottom"] #ui input[type=range] {
      width: 100%;
    }

    body[data-ui-layout="right"] #ui textarea,
    body[data-ui-layout="bottom"] #ui textarea {
      width: 100%;
      box-sizing: border-box;
      min-height: 180px;
      resize: vertical;
      font-family: ui-monospace, Consolas, monospace;
      font-size: 11px;
      line-height: 1.45;
      tab-size: 2;
      border: 1px solid #cfd4da;
      border-radius: 4px;
      padding: 6px 8px;
    }

    body[data-ui-layout="bottom"] #ui textarea {
      min-height: 110px;
    }

    /* ── Inline equation parse errors ────────────────────────────────────── */
    .eq-err {
      color: #c00000;
      font-size: 10px;
      max-width: 180px;
      white-space: normal;
      text-shadow: 0 1px 2px #fff;
    }

    /* ── Hover tooltip ───────────────────────────────────────────────────── */
    #figTooltip {
      position: fixed;
      left: 0;
      top: 0;
      display: none;
      max-width: 210px;
      padding: 4px 8px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.58);
      color: #fff;
      font: 11px/1.35 sans-serif;
      pointer-events: none;
      white-space: normal;
      z-index: 20;
    }
  </style>
</head>

<body data-ui-layout="right">
  <div id="container"></div>
  <div id="figTooltip"></div>
  <div id="ui">
    <!-- @FIGURE_UI_BEGIN -->
    <!-- @FIGURE_UI_END -->
  </div>

  <!-- Error overlay: shown if CDN fails or JS throws before rendering -->
  <div id="err-overlay" style="display:none;position:fixed;inset:0;background:#fff;z-index:999;
       flex-direction:column;align-items:center;justify-content:center;
       font-family:sans-serif;font-size:13px;color:#555;gap:10px;">
    <span id="err-msg">⚠ Figure failed to load</span>
    <button onclick="location.reload()" style="padding:5px 14px;border:1px solid #aaa;
        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    /* ── Error overlay ───────────────────────────────────────────────────── */
    var _rendered = false;
    var _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = function () { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', function (e) {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    setTimeout(function () { if (!_rendered) { _errOverlay.style.display = 'flex'; } }, 12000);

    /* ── Tooltip + popup helpers ─────────────────────────────────────────── */
    var _tooltip = document.getElementById('figTooltip');

    function showPopup(title, body) {
      window.parent.postMessage({ type: 'alex-popup', title: title, body: body }, '*');
    }
    function hidePopup() {
      window.parent.postMessage({ type: 'alex-popup', title: null }, '*');
    }
    function showTooltip(text, event) {
      if (!_tooltip || !text) return;
      _tooltip.textContent = text;
      _tooltip.style.display = 'block';
      _moveTooltip(event);
    }
    function _moveTooltip(event) {
      if (!_tooltip || _tooltip.style.display === 'none') return;
      var pad = 12;
      var x = Math.min(event.clientX + pad, window.innerWidth - (_tooltip.offsetWidth || 100) - pad);
      var y = Math.max(pad, event.clientY - (_tooltip.offsetHeight || 40) - pad);
      _tooltip.style.left = x + 'px';
      _tooltip.style.top = y + 'px';
    }
    function hideTooltip() {
      if (_tooltip) _tooltip.style.display = 'none';
    }
    document.addEventListener('mousemove', function (e) { _moveTooltip(e); });

    /* ── Resize event ────────────────────────────────────────────────────── */
    function _containerInnerSize() {
      var container = document.getElementById('container');
      var style = getComputedStyle(container);
      var padX = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
      var padY = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
      return {
        width: Math.max(0, container.clientWidth - padX),
        height: Math.max(0, container.clientHeight - padY)
      };
    }

    new ResizeObserver(function () {
      var rect = _containerInnerSize();
      document.dispatchEvent(new CustomEvent('fig-resize', {
        detail: { width: rect.width, height: rect.height }
      }));
    }).observe(document.getElementById('container'));

    /* ── UI layout: keep controls in a right-side column ─────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     * Docking resizes #container, which fires 'fig-resize', so setPlotFrame
     * re-lays the figure out at its new size instead of it being covered.
     */
    var _uiEl = document.getElementById('ui');

    function setUiLayout(mode, sizePx) {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      var next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', sizePx + 'px');
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    var _autoUiTimer = 0;
    function _autoUiLayout() {
      var hasEditor = Boolean(_uiEl.querySelector('textarea'));
      var mode = 'right';
      var start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      var cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      var size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', size + 'px');
      var guard = 0;
      function step() {
        if (guard++ > 6) return;
        if (_uiEl.scrollHeight <= _uiEl.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', size + 'px');
        requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    window.__autoUiLayout = _autoUiLayout;

    // Re-evaluate when generated code adds controls after first paint.
    new MutationObserver(function () {
      clearTimeout(_autoUiTimer);
      _autoUiTimer = setTimeout(_autoUiLayout, 0);
    }).observe(_uiEl, { childList: true, subtree: true });
    window.addEventListener('resize', function () { _autoUiLayout(); });

    /* ── Keyboard dismiss ────────────────────────────────────────────────── */
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { hidePopup(); hideTooltip(); }
    });

    /* ── Expression parsing ──────────────────────────────────────────────── */
    /**
     * compileExpr(src, vars) → function(...args)
     *   src  : math source, e.g. 'sin(x) + 1', 'x^2', '2*x - 3'
     *   vars : variable names in argument order, e.g. ['x'] or ['x', 'y']
     * Throws an Error with a readable message on a syntax error or when the
     * source references a variable outside `vars`. Never returns a fallback.
     *
     * DUPLICATED (deliberately): base_scene_new.html has an equivalent ES-module
     * copy. Each scaffold is a standalone served HTML file and neither can
     * import the other, so behaviour changes must be made TWICE.
     * Keep this in sync with compileExpr in base_scene_new.html.
     */
    function compileExpr(src, vars) {
      if (!window.exprEval || !window.exprEval.Parser) {
        throw new Error('Expression parser unavailable (expr-eval CDN did not load)');
      }
      var names = (vars && vars.length) ? vars : ['x'];
      var parsed;
      try {
        parsed = new window.exprEval.Parser().parse(String(src));
      } catch (e) {
        throw new Error('Cannot parse "' + src + '": ' + ((e && e.message) ? e.message : e));
      }
      var used = parsed.variables();
      for (var i = 0; i < used.length; i++) {
        if (names.indexOf(used[i]) === -1) {
          throw new Error('Unknown variable "' + used[i] + '" (expected: ' + names.join(', ') + ')');
        }
      }
      return function () {
        var scope = {};
        for (var j = 0; j < names.length; j++) scope[names[j]] = arguments[j];
        var v;
        try { v = parsed.evaluate(scope); } catch (e) { return NaN; }
        return (typeof v === 'number') ? v : NaN;
      };
    }

    /* ── Plot frame: world → screen mapping (owns resize) ────────────────── */
    var _plotFrame = null;
    var _plots = [];
    var _plotResizeBound = false;

    /**
     * setPlotFrame({ xDomain, yDomain, margin, draw }) → frame
     * Establishes the world→screen mapping used by plotX / plotY and by every
     * plot helper. Call this once, before creating any plots. Registered plots
     * are re-sampled automatically on resize.
     */
    function setPlotFrame(opts) {
      opts = opts || {};
      var innerSize = _containerInnerSize();
      _plotFrame = {
        xDomain: opts.xDomain || [-5, 5],
        yDomain: opts.yDomain || [-5, 5],
        margin: (opts.margin == null) ? 24 : opts.margin,
        draw: opts.draw || SVG().addTo('#container').size('100%', '100%'),
        width: innerSize.width || 900,
        height: innerSize.height || 600
      };
      _recomputePlotScale();
      if (!_plotResizeBound) {
        _plotResizeBound = true;
        document.addEventListener('fig-resize', function (e) {
          if (!_plotFrame) return;
          _plotFrame.width = e.detail.width || _plotFrame.width;
          _plotFrame.height = e.detail.height || _plotFrame.height;
          _recomputePlotScale();
          for (var i = 0; i < _plots.length; i++) _plots[i].sample();
        });
      }
      return _plotFrame;
    }

    function _recomputePlotScale() {
      var f = _plotFrame, m = f.margin;
      f.sx = (f.width - 2 * m) / (f.xDomain[1] - f.xDomain[0]);
      f.sy = (f.height - 2 * m) / (f.yDomain[1] - f.yDomain[0]);
    }

    /** plotX(worldX) → screen px. Requires setPlotFrame() first. */
    function plotX(wx) {
      var f = _plotFrame;
      return f.margin + (wx - f.xDomain[0]) * f.sx;
    }

    /** plotY(worldY) → screen px (y axis flipped). Requires setPlotFrame() first. */
    function plotY(wy) {
      var f = _plotFrame;
      return f.height - f.margin - (wy - f.yDomain[0]) * f.sy;
    }

    function _registerPlot(handle) {
      _plots.push(handle);
      return handle;
    }

    function _unregisterPlot(handle) {
      var i = _plots.indexOf(handle);
      if (i >= 0) _plots.splice(i, 1);
    }

    function _resolveFn(value, vars) {
      if (typeof value === 'function') return value;
      return compileExpr(value, vars);
    }

    function _pointsAttr(points) {
      return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    }

    /**
     * plotFunction(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain, samples=200,
     *           stroke='#1f77b4', width=2, dashed=false }
     * The drawn polyline is ALWAYS produced by sampling the compiled function
     * across `domain`. Non-finite samples split the line into segments instead
     * of drawing a spike.
     */
    function plotFunction(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'plot-' + id);
      var handle = {
        id: id,
        node: group,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setExpr: function (src) { this.fn = _resolveFn(src, vars); return this.sample(); },
        setFn: function (f) { this.fn = f; return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          if (!this.fn) return this;
          var segs = _sampleSegments(this.fn, this.domain, this.samples);
          for (var s = 0; s < segs.length; s++) {
            if (segs[s].length < 2) continue;
            var line = group.polyline(_pointsAttr(segs[s]))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4',
                width: opts.width || 2,
                linecap: 'round',
                linejoin: 'round'
              });
            if (opts.dashed) line.attr('stroke-dasharray', '5,4');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** Sample fn across domain, splitting at non-finite values. → [[ [px,py], … ], …] */
    function _sampleSegments(fn, domain, samples) {
      var a = domain[0], b = domain[1], n = Math.max(2, samples | 0);
      var segs = [], cur = [];
      for (var i = 0; i < n; i++) {
        var t = a + (b - a) * (i / (n - 1));
        var v;
        try { v = fn(t); } catch (e) { v = NaN; }
        if (typeof v === 'number' && isFinite(v)) {
          cur.push([plotX(t), plotY(v)]);
        } else if (cur.length) {
          segs.push(cur);
          cur = [];
        }
      }
      if (cur.length) segs.push(cur);
      return segs;
    }

    /**
     * fillBetween(id, opts) → handle
     *   opts: { lower, upper, variables=['x'], domain, samples=200,
     *           fill='#7fb3ff', opacity=0.45, stroke, strokeWidth=1 }
     * `lower` / `upper` may be expression strings or functions. The polygon is
     * built from EVERY sampled point on both boundaries, so a curved boundary
     * produces a curved region with no caller involvement.
     */
    function fillBetween(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'fill-' + id);
      var handle = {
        id: id,
        node: group,
        lower: opts.lower != null ? _resolveFn(opts.lower, vars) : function () { return 0; },
        upper: opts.upper != null ? _resolveFn(opts.upper, vars) : function () { return 0; },
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setLower: function (src) { this.lower = _resolveFn(src, vars); return this.sample(); },
        setUpper: function (src) { this.upper = _resolveFn(src, vars); return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.domain[0], b = this.domain[1], n = Math.max(2, this.samples | 0);
          var top = [], bottom = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: SVG.js v3 (global: SVG). var draw=SVG().addTo(document.getElementById('container')).size('100%','100%'); var W=600,H=Math.round(W*(3/4)); draw.viewbox(0,0,W,H). font-size in user units (no px). Hover: el.on('mousemove',e=>showTooltip('label',e)).on('mouseleave',()=>hideTooltip()).on('click',()=>showPopup('Title','body')); el.css('cursor','pointer'). window.__markRendered() synchronously at end.
PLOTTING HELPERS (do not re-declare, and do NOT define your own X()/Y() — use plotX/plotY):
  setPlotFrame({ xDomain, yDomain, margin }) → call ONCE before creating plots; establishes world→screen and owns resize (do not write your own plot resize handler)
  plotX(worldX) / plotY(worldY) → screen px
  compileExpr(src, vars) → f(...args); throws on a bad expression and never returns a fallback
  bindEquationInput(inputId, targets, { variables, onChange }) → wires an <input> to plot handles and shows parse errors inline
  plotFunction(id, { expr, variables, domain, samples, stroke, width, dashed }) → handle
  fillBetween(id, { lower, upper, variables, domain, samples, fill, opacity }) → handle
  plotParametric(id, { x, y, variables, tDomain, samples, stroke }) → handle
  variables: the argument names the expression may use, in order (defaults: plotFunction ['x'], fillBetween ['x'], plotParametric ['t']). When a blueprint field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotFunction('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  integrateSimpson(fn, a, b, n) → number;  findRoot(fn, a, b, tol) → number | null
  Handles re-sample on EVERY setter call, and the setters differ: plotFunction → .setExpr / .setFn / .setDomain · fillBetween → .setLower / .setUpper / .setDomain · plotParametric → .setX / .setY. All handles also have .sample() and .remove().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Training a model means moving a point through parameter space: every (intercept φ₀, slope φ₁) pair is one location on the loss surface and one line through the data, and gradient descent walks downhill on the surface until the line fits.
KEY INSIGHT (what students should walk away understanding): A point on the loss surface and a line through the data are the same object seen twice — descending the surface and fitting the data are literally one motion.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Training a model means moving a point through parameter space: every (intercept φ₀, slope φ₁) pair is one location on the loss surface and one line through the data, and gradient descent walks downhill on the surface until the line fits.",
  "figureType": "other",
  "elements": [
    "Two side-by-side panels with labels 'a)' (left) and 'b)' (right)",
    "Panel a title: 'Loss, L[φ]'",
    "Panel a: filled contour heatmap of the least-squares loss over parameter space, dark red-brown at the basin, lightening to pale cream toward the upper-left and right edges, with thin light-grey iso-loss contour rings forming a tilted elliptical bowl",
    "Panel a x-axis: 'Intercept, φ₀', ticks at 0.0, 1.0, 2.0",
    "Panel a y-axis: 'Slope, φ₁', ticks at -1.0 (top), 0.0, 1.0 (bottom) — axis is inverted, slope increases downward",
    "Panel a: gradient-descent path — 5 circular markers numbered 0,1,2,3,4 connected by a thick grey polyline with a small arrowhead into marker 4",
    "Panel a: marker colors ramp with iteration from pale teal #b4e1dd (0) through #8bd0c9, #4db7aa to dark teal #2f7870 (4); white numeric labels beside each marker",
    "Panel a: draggable current-parameter marker (highlighted ring) sitting on the path",
    "Panel b x-axis: 'Input, x', ticks 0.0, 1.0, 2.0",
    "Panel b y-axis: 'Output, y', ticks 0.0, 1.0, 2.0",
    "Panel b: ~12 salmon/terracotta (#c8674a) scatter points of training data lying along a rising trend from about (0.05, 0.75) to (1.9, 1.6)",
    "Panel b: five straight fitted lines, one per iteration, colored with the same pale-to-dark teal ramp; line 0 nearly flat and low, each successive line steeper/higher, line 4 (dark teal) passing through the data cloud",
    "Panel b: small teal numerals 0,1,2,3,4 labelling each line near the left edge, with a curved grey arrow sweeping from label 0 up to label 4 showing the progression",
    "Panel b: highlighted 'current' fitted line corresponding to the draggable marker",
    "Optional residual segments from each data point to the current line",
    "Loss readout annotation showing L[φ] for the current parameter pair"
  ],
  "interactions": [
    {
      "id": "dragParams",
      "type": "drag",
      "teaches": "That one point in parameter space IS one line in data space — dragging the marker anywhere on the loss surface instantly redraws the fitted line, and the darker the region, the worse the fit."
    },
    {
      "id": "intercept",
      "type": "slider",
      "label": "Intercept, φ₀",
      "range": [
        0,
        2,
        0.01
      ],
      "default": 0.12,
      "teaches": "Changing φ₀ alone slides the marker horizontally across the loss contours while the fitted line shifts up or down without changing its tilt."
    },
    {
      "id": "slope",
      "type": "slider",
      "label": "Slope, φ₁",
      "range": [
        -1,
        1,
        0.01
      ],
      "default": -0.13,
      "teaches": "Changing φ₁ alone slides the marker vertically across the contours while the fitted line pivots, showing that the two parameters move the point along independent axes of the same surface."
    },
    {
      "id": "descentStep",
      "type": "button",
      "label": "Gradient descent step",
      "states": [
        "0",
        "1",
        "2",
        "3",
        "4"
      ],
      "default": "0",
      "teaches": "That optimization is a sequence of downhill steps: each click moves the marker toward the basin and visibly tightens the line against the data."
    },
    {
      "id": "showResiduals",
      "type": "toggle",
      "label": "Show residuals",
      "options": [
        "hidden",
        "shown"
      ],
      "default": "hidden",
      "teaches": "That the height of the loss surface is literally the sum of squared vertical gaps drawn in the data panel."
    }
  ],
  "demo_steps": [
    {
      "title": "A bad guess",
      "narration": "We start at point 0: a small intercept and a slightly negative slope. On the loss surface the marker sits in a dark, high-loss region; in the data panel the corresponding line is flat and far below the points.",
      "state": {
        "descentStep": "0",
        "intercept": 0.12,
        "slope": -0.13,
        "showResiduals": "hidden"
      }
    },
    {
      "title": "Loss = summed squared errors",
      "narration": "Turn on the residuals. Each grey stub is one data point's error; the height of the loss surface at the marker is just the sum of their squares.",
      "state": {
        "descentStep": "0",
        "showResiduals": "shown"
      }
    },
    {
      "title": "Move the intercept only",
      "narration": "Push φ₀ to the right. The marker travels horizontally across the contours and the line rises bodily without tilting — the loss drops, but only partway.",
      "state": {
        "intercept": 0.85,
        "slope": -0.13,
        "showResiduals": "shown"
      }
    },
    {
      "title": "Move the slope only",
      "narration": "Now increase φ₁. The marker drops vertically into the light-centred basin and the line rotates to match the trend of the data.",
      "state": {
        "intercept": 0.85,
        "slope": 0.5,
        "showResiduals": "shown"
      }
    },
    {
      "title": "Let gradient descent do it",
      "narration": "Step the optimizer. Each click takes one downhill step from 0 to 4; the steps shorten as the surface flattens near the minimum, and the fitted lines fan up toward the data.",
      "state": {
        "descentStep": "4",
        "showResiduals": "hidden"
      }
    },
    {
      "title": "Explore off the path",
      "narration": "Drag the marker anywhere on the surface. Every location you can reach is a legal model — the whole job of training is finding the one at the bottom of the bowl.",
      "state": {
        "descentStep": "4",
        "showResiduals": "shown"
      }
    }
  ],
  "keyInsight": "A point on the loss surface and a line through the data are the same object seen twice — descending the surface and fitting the data are literally one motion.",
  "reconstructionNotes": "Two equal-size square panels side by side. Left panel 'a)': a tilted elliptical loss bowl rendered as a smooth heatmap, darkest (deep red-brown) at the basin running diagonally from lower-left to upper-right, lightening to cream in the far upper-left corner and along the right edge; overlay ~15 thin light-grey iso-loss contours. x-axis 'Intercept, φ₀' 0→2, y-axis 'Slope, φ₁' labelled -1.0 at the TOP and 1.0 at the BOTTOM (inverted axis). Draw the descent path as a thick grey polyline over 5 filled circles labelled 0–4 in white, starting upper-left around (0.12, -0.13) and curving down-right to about (0.85, 0.50), with steps clearly shrinking and a small arrowhead entering marker 4; marker fill ramps pale teal #b4e1dd → #8bd0c9 → #4db7aa → #2f7870. Right panel 'b)': white background, axes 'Input, x' and 'Output, y' both 0→2. Scatter ~12 terracotta (#c8674a) dots with white edges rising roughly linearly with mild noise from near (0.05,0.75) to (1.9,1.6). Five straight fitted lines in the same teal ramp, all clipped to the axes: line 0 nearly horizontal and low, lines 1–3 progressively steeper and higher, line 4 the darkest and best-fitting; number each line 0–4 in matching teal near the left edge and add a curved grey arrow sweeping from 0 up to 4. Highlight the currently selected parameter marker and its line with extra weight. Keep the two panels visually linked: any change in parameter space must animate the corresponding line in data space in the same frame."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0 0 2px 0;font-size:12px;line-height:1.45"></p>
<span style="display:flex;align-items:center;gap:8px;margin:0 0 4px 0"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px;color:#555"></span><button onclick="nextStep()">▶</button></span>
<label>Intercept, &phi;<sub>0</sub>: <output id="interceptVal">0.12</output><input id="interceptInput" type="range" min="0" max="2" step="0.01" value="0.12" oninput="document.getElementById('interceptVal').value=this.value;update_intercept(+this.value)"></label>
<label>Slope, &phi;<sub>1</sub>: <output id="slopeVal">-0.13</output><input id="slopeInput" type="range" min="-1" max="1" step="0.01" value="-0.13" oninput="document.getElementById('slopeVal').value=this.value;update_slope(+this.value)"></label>
<button onclick="trigger_descentStep()">Gradient descent step (<output id="descentStepVal">0</output>/4)</button>
<label><input id="showResidualsInput" type="checkbox" onchange="toggle_showResiduals(this.checked)"> Show residuals</label>
<span style="font-size:11px;color:#666;line-height:1.4">Drag the ringed marker anywhere on the loss surface — the fitted line in panel b) follows in the same frame.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var FONT = 'Helvetica Neue, Helvetica, Arial, sans-serif';
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var VW = 1030, VH = 560;
  draw.viewbox(0, 0, VW, VH).attr('preserveAspectRatio', 'xMidYMid meet');

  /* ── panel geometry ──────────────────────────────────────────── */
  var A = { x: 95, y: 55, s: 400 };
  var B = { x: 600, y: 55, s: 400 };
  function aX(p0) { return A.x + p0 / 2 * A.s; }
  function aY(p1) { return A.y + (p1 + 1) / 2 * A.s; }
  function bX(x) { return B.x + x / 2 * B.s; }
  function bY(y) { return B.y + B.s - y / 2 * B.s; }

  /* ── data & loss ─────────────────────────────────────────────── */
  var data = [[0.05, 0.75], [0.18, 0.88], [0.30, 1.07], [0.47, 1.00], [0.79, 1.33],
  [0.80, 1.47], [1.07, 1.28], [1.20, 1.48], [1.40, 1.48], [1.60, 1.65],
  [1.68, 1.70], [1.92, 1.58]];
  var Nd = data.length;
  function loss(p0, p1) {
    var s = 0;
    for (var i = 0; i < Nd; i++) { var r = p0 + p1 * data[i][0] - data[i][1]; s += r * r; }
    return s / Nd;
  }
  var mx = 0, my = 0, mxx = 0, mxy = 0;
  for (var i = 0; i < Nd; i++) { mx += data[i][0]; my += data[i][1]; mxx += data[i][0] * data[i][0]; mxy += data[i][0] * data[i][1]; }
  mx /= Nd; my /= Nd; mxx /= Nd; mxy /= Nd;
  var bestP1 = (mxy - mx * my) / (mxx - mx * mx);
  var bestP0 = my - bestP1 * mx;
  var Lmin = loss(bestP0, bestP1);

  /* ── loss surface heat map (canvas → image) ──────────────────── */
  var NG = 200;
  var lv = new Float64Array(NG * NG), Lmax = -1e18;
  for (var j = 0; j < NG; j++) {
    var p1g = -1 + (j + 0.5) / NG * 2;
    for (var ii = 0; ii < NG; ii++) {
      var p0g = (ii + 0.5) / NG * 2;
      var L = loss(p0g, p1g);
      lv[j * NG + ii] = L;
      if (L > Lmax) Lmax = L;
    }
  }
  var stops = [[0.00, [38, 13, 9]], [0.16, [64, 22, 15]], [0.36, [112, 48, 33]],
  [0.58, [166, 98, 70]], [0.80, [214, 166, 131]], [1.00, [250, 239, 220]]];
  function cmap(t) {
    t = t < 0 ? 0 : (t > 1 ? 1 : t);
    for (var k = 1; k < stops.length; k++) {
      if (t <= stops[k][0]) {
        var a = stops[k - 1], b = stops[k], u = (t - a[0]) / (b[0] - a[0]);
        return [Math.round(a[1][0] + (b[1][0] - a[1][0]) * u),
        Math.round(a[1][1] + (b[1][1] - a[1][1]) * u),
        Math.round(a[1][2] + (b[1][2] - a[1][2]) * u)];
      }
    }
    return stops[stops.length - 1][1];
  }
  var cvs = document.createElement('canvas');
  cvs.width = NG; cvs.height = NG;
  var ctx = cvs.getContext('2d');
  var idat = ctx.createImageData(NG, NG);
  for (var q = 0; q < NG * NG; q++) {
    var nrm = (lv[q] - Lmin) / (Lmax - Lmin);
    var c = cmap(Math.pow(nrm < 0 ? 0 : nrm, 0.6));
    idat.data[q * 4] = c[0]; idat.data[q * 4 + 1] = c[1]; idat.data[q * 4 + 2] = c[2]; idat.data[q * 4 + 3] = 255;
  }
  ctx.putImageData(idat, 0, 0);
  draw.image(cvs.toDataURL()).size(A.s, A.s).move(A.x, A.y).attr('preserveAspectRatio', 'none');

  /* ── analytic iso-loss contours (tilted ellipses) ────────────── */
  var a11 = 1, a12 = mx, a22 = mxx;
  var trh = (a11 + a22) / 2, disc = Math.sqrt(Math.pow((a11 - a22) / 2, 2) + a12 * a12);
  var l1 = trh + disc, l2 = trh - disc;
  function evec(l) { var vx = a12, vy = l - a11, n = Math.hypot(vx, vy); return n < 1e-12 ? [1, 0] : [vx / n, vy / n]; }
  var v1 = evec(l1), v2 = evec(l2);

  var cpA = draw.clip().add(draw.rect(A.s, A.s).move(A.x, A.y));
  var gCont = draw.group().attr('clip-path', 'url(#' + cpA.id() + ')');
  var rmax = (Lmax - Lmin) * 1.12;
  for (var k = 1; k <= 16; k++) {
    var r = rmax * Math.pow(k / 16, 2);
    var pts = [];
    for (var t = 0; t <= 240; t++) {
      var th = t / 240 * Math.PI * 2;
      var c1 = Math.cos(th) * Math.sqrt(r / l1), c2 = Math.sin(th) * Math.sqrt(r / l2);
      var q0 = bestP0 + c1 * v1[0] + c2 * v2[0];
      var q1 = bestP1 + c1 * v1[1] + c2 * v2[1];
      pts.push([aX(q0), aY(q1)]);
    }
    gCont.polyline(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
      .fill('none').stroke({ color: '#ded5d0', width: 1.1, opacity: 0.62, linejoin: 'round' });
  }

  /* ── drag overlay on panel a ─────────────────────────────────── */
  var overlay = draw.rect(A.s, A.s).move(A.x, A.y).fill({ color: '#000', opacity: 0 }).css('cursor', 'crosshair');

  /* ── gradient-descent iterates ───────────────────────────────── */
  var iter = [[0.12, -0.13], [0.42, 0.22], [0.58, 0.36], [0.72, 0.43], [0.86, 0.47]];
  var ramp = ['#b4e1dd', '#8bd0c9', '#4db7aa', '#3a9489', '#2f7870'];

  function arrowHead(g, x, y, dx, dy, size, color) {
    var n = Math.hypot(dx, dy) || 1; dx /= n; dy /= n;
    var px = -dy, py = dx;
    var p = [[x, y],
    [x - dx * size + px * size * 0.55, y - dy * size + py * size * 0.55],
    [x - dx * size - px * size * 0.55, y - dy * size - py * size * 0.55]];
    g.polygon(p.map(function (v) { return v[0] + ',' + v[1]; }).join(' ')).fill(color).stroke('none');
  }

  var gPath = draw.group();
  gPath.polyline(iter.map(function (p) { return aX(p[0]) + ',' + aY(p[1]); }).join(' '))
    .fill('none').stroke({ color: '#9a9a9a', width: 5, linecap: 'round', linejoin: 'round' });
  (function () {
    var p3 = iter[3], p4 = iter[4];
    var x3 = aX(p3[0]), y3 = aY(p3[1]), x4 = aX(p4[0]), y4 = aY(p4[1]);
    var dx = x4 - x3, dy = y4 - y3, n = Math.hypot(dx, dy);
    arrowHead(gPath, x4 - dx / n * 10, y4 - dy / n * 10, dx, dy, 12, '#9a9a9a');
  })();

  var numOff = [[-4, 23], [-4, 23], [0, 25], [1, 26], [17, 8]];
  for (var m = 0; m < iter.length; m++) {
    (function (k) {
      var cx = aX(iter[k][0]), cy = aY(iter[k][1]);
      var cir = gPath.circle(17).center(cx, cy).fill(ramp[k]).stroke('none').css('cursor', 'pointer');
      cir.on('mousemove', function (e) {
        showTooltip('Iterate ' + k + ':  φ₀=' + iter[k][0].toFixed(2) + ', φ₁=' + iter[k][1].toFixed(2) +
          '   L[φ]=' + loss(iter[k][0], iter[k][1]).toFixed(3), e);
      }).on('mouseleave', hideTooltip);
      cir.on('mousedown', function () { setStep(k); });
      cir.on('click', function () {
        showPopup('Iterate ' + k,
          'This point is the parameter pair after ' + k + ' gradient-descent step' + (k === 1 ? '' : 's') +
          ': φ₀=' + iter[k][0].toFixed(2) + ', φ₁=' + iter[k][1].toFixed(2) + ', loss ' +
          loss(iter[k][0], iter[k][1]).toFixed(3) + '. The teal line with the same number in panel b) is the very same model, drawn in data space.');
      });
      var lab = gPath.plain(String(k)).font({ family: FONT, size: 17 }).fill('#ffffff');
      lab.attr({ x: cx + numOff[k][0], y: cy + numOff[k][1], 'text-anchor': 'middle', 'dominant-baseline': 'central' });
    })(m);
  }

  /* current marker on the surface */
  var curRing = draw.circle(26).center(aX(iter[0][0]), aY(iter[0][1])).fill('none')
    .stroke({ color: '#ffffff', width: 2 }).opacity(0.9);
  var curMarker = draw.circle(19).center(aX(iter[0][0]), aY(iter[0][1])).fill(ramp[0])
    .stroke({ color: '#ffffff', width: 2 }).css('cursor', 'grab');

  /* panel a frame + loss readout */
  draw.rect(A.s, A.s).move(A.x, A.y).fill('none').stroke({ color: '#1a1a1a', width: 2 });
  var lossText = draw.plain('L[φ] = 0.000').font({ family: FONT, size: 15 }).fill('#ffffff');
  lossText.attr({ x: A.x + A.s - 12, y: A.y + A.s - 16, 'text-anchor': 'end', 'dominant-baseline': 'central' });

  /* ── panel b content ─────────────────────────────────────────── */
  var cpB = draw.clip().add(draw.rect(B.s, B.s).move(B.x, B.y));
  var gB = draw.group().attr('clip-path', 'url(#' + cpB.id() + ')');
  var gLines = gB.group(), gRes = gB.group(), gCur = gB.group(), gPts = gB.group();

  for (var m2 = 0; m2 < iter.length; m2++) {
    (function (k) {
      var p0 = iter[k][0], p1 = iter[k][1];
      var ln = gLines.line(bX(0), bY(p0), bX(2), bY(p0 + 2 * p1))
        .stroke({ color: ramp[k], width: 4.2, linecap: 'round' }).css('cursor', 'pointer');
      ln.on('mousemove', function (e) {
        showTooltip('Line ' + k + ':  y = ' + p0.toFixed(2) + ' + ' + p1.toFixed(2) + ' x', e);
      }).on('mouseleave', hideTooltip);
      ln.on('click', function () {
        setStep(k);
        showPopup('Line ' + k + ' = point ' + k,
          'Every straight line here is one dot on the loss surface at left. Choosing (φ₀, φ₁) = (' +
          p0.toFixed(2) + ', ' + p1.toFixed(2) + ') is the same act as placing the marker there; the loss is ' +
          loss(p0, p1).toFixed(3) + '.');
      });
    })(m2);
  }

  var curLine = gCur.line(0, 0, 0, 0).stroke({ color: ramp[0], width: 5.6, linecap: 'round' }).css('cursor', 'pointer');
  curLine.on('mousemove', function (e) {
    showTooltip('Current model:  y = ' + st.p0.toFixed(2) + ' + ' + st.p1.toFixed(2) + ' x   (L = ' + loss(st.p0, st.p1).toFixed(3) + ')', e);
  }).on('mouseleave', hideTooltip);
  curLine.on('click', function () {
    showPopup('One object, seen twice',
      'This line and the ringed marker on the loss surface are the same model. Descending the surface and fitting the data are literally one motion — move one and the other moves with it.');
  });

  for (var d = 0; d < Nd; d++) {
    (function (pt) {
      var c = gPts.circle(16).center(bX(pt[0]), bY(pt[1])).fill('#c8674a')
        .stroke({ color: '#ffffff', width: 1.6 }).css('cursor', 'pointer');
      c.on('mousemove', function (e) {
        var pred = st.p0 + st.p1 * pt[0];
        showTooltip('data (x=' + pt[0].toFixed(2) + ', y=' + pt[1].toFixed(2) + ')\nprediction ' + pred.toFixed(2) +
          ', error ' + (pred - pt[1]).toFixed(2), e);
      }).on('mouseleave', hideTooltip);
    })(data[d]);
  }

  /* panel b spines */
  draw.line(bX(0), bY(0), bX(0), bY(2)).stroke({ color: '#111', width: 2.5 });
  draw.line(bX(0), bY(0), bX(2), bY(0)).stroke({ color: '#111', width: 2.5 });

  /* line number labels */
  for (var m3 = 0; m3 < iter.length; m3++) {
    var lx = (m3 === 0) ? bX(0.33) : bX(0.075);
    var lyv = (m3 === 0) ? 0.055 : iter[m3][0] - 0.075;
    var tl = draw.plain(String(m3)).font({ family: FONT, size: 18 }).fill(ramp[m3]);
    tl.attr({ x: lx, y: bY(lyv), 'text-anchor': 'middle', 'dominant-baseline': 'central' });
    tl.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  }
  /* curved progression arrow */
  (function () {
    var sx = bX(0.42), sy = bY(0.10), cx = bX(0.54), cy = bY(0.50), ex = bX(0.145), ey = bY(0.80);
    draw.path('M ' + sx + ' ' + sy + ' Q ' + cx + ' ' + cy + ' ' + ex + ' ' + ey)
      .fill('none').stroke({ color: '#b3b3b3', width: 3.2, linecap: 'round' });
    var g2 = draw.group();
    arrowHead(g2, ex, ey, ex - cx, ey - cy, 12, '#b3b3b3');
  })();

  /* ── axes decoration ────────────────────────────────────────── */
  function plainLabel(str, x, y, size, color, anchor) {
    var t = draw.plain(str).font({ family: FONT, size: size }).fill(color);
    t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'central' });
    return t;
  }
  function mathLabel(upright, mathStr, size, color) {
    var outer = draw.group(), inner = outer.group();
    var t1 = inner.plain(upright).font({ family: FONT, size: size }).fill(color);
    t1.attr({ x: 0, y: 0, 'text-anchor': 'start', 'dominant-baseline': 'central' });
    var w1 = t1.bbox().width;
    var t2 = inner.plain(mathStr).font({ family: FONT, size: size, style: 'italic' }).fill(color);
    t2.attr({ x: w1 + size * 0.26, y: 0, 'text-anchor': 'start', 'dominant-baseline': 'central' });
    var bb = inner.bbox();
    inner.attr('transform', 'translate(' + (-bb.x - bb.width / 2) + ',' + (-bb.y - bb.height / 2) + ')');
    return outer;
  }

  var TC = '#555', TT = '#222';
  /* panel a ticks */
  [[0, '0.0'], [1, '1.0'], [2, '2.0']].forEach(function (tk) {
    draw.line(aX(tk[0]), A.y + A.s, aX(tk[0]), A.y + A.s + 7).stroke({ color: TC, width: 1.4 });
    plainLabel(tk[1], aX(tk[0]), A.y + A.s + 22, 15, TC);
  });
  [[-1, '-1.0'], [0, '0.0'], [1, '1.0']].forEach(function (tk) {
    draw.line(A.x - 7, aY(tk[0]), A.x, aY(tk[0])).stroke({ color: TC, width: 1.4 });
    plainLabel(tk[1], A.x - 12, aY(tk[0]), 15, TC, 'end');
  });
  mathLabel('Intercept,', 'φ₀', 20, TT).attr('transform', 'translate(' + (A.x + A.s / 2) + ',' + (A.y + A.s + 55) + ')');
  mathLabel('Slope,', 'φ₁', 20, TT).attr('transform', 'translate(36,' + (A.y + A.s / 2) + ') rotate(-90)');
  mathLabel('Loss,', 'L[φ]', 21, TT).attr('transform', 'translate(' + (A.x + A.s / 2) + ',30)');

  /* panel b ticks */
  [[0, '0.0'], [1, '1.0'], [2, '2.0']].forEach(function (tk) {
    draw.line(bX(tk[0]), bY(0), bX(tk[0]), bY(0) + 7).stroke({ color: TC, width: 1.4 });
    plainLabel(tk[1], bX(tk[0]), bY(0) + 22, 15, TC);
    draw.line(bX(0) - 7, bY(tk[0]), bX(0), bY(tk[0])).stroke({ color: TC, width: 1.4 });
    plainLabel(tk[1], bX(0) - 12, bY(tk[0]), 15, TC, 'end');
  });
  mathLabel('Input,', 'x', 20, TT).attr('transform', 'translate(' + (B.x + B.s / 2) + ',' + (B.y + B.s + 55) + ')');
  mathLabel('Output,', 'y', 20, TT).attr('transform', 'translate(546,' + (B.y + B.s / 2) + ') rotate(-90)');

  plainLabel('a)', 14, 20, 24, TT, 'start');
  plainLabel('b)', 528, 20, 24, TT, 'start');

  /* ── state & rendering ──────────────────────────────────────── */
  var st = { p0: iter[0][0], p1: iter[0][1], step: 0 };
  var showRes = false;

  function syncUI() {
    var si = document.getElementById('interceptInput'), ss = document.getElementById('slopeInput');
    if (si) { si.value = st.p0; document.getElementById('interceptVal').value = st.p0.toFixed(2); }
    if (ss) { ss.value = st.p1; document.getElementById('slopeVal').value = st.p1.toFixed(2); }
    var ds = document.getElementById('descentStepVal');
    if (ds) ds.value = (st.step >= 0 ? String(st.step) : '–');
    var cb = document.getElementById('showResidualsInput');
    if (cb) cb.checked = showRes;
  }

  function render() {
    var p0 = st.p0, p1 = st.p1;
    var col = st.step >= 0 ? ramp[st.step] : '#12635b';
    curMarker.center(aX(p0), aY(p1)).fill(col);
    curRing.center(aX(p0), aY(p1));
    curLine.plot(bX(0), bY(p0), bX(2), bY(p0 + 2 * p1)).stroke({ color: col, width: 5.6 });
    gRes.clear();
    if (showRes) {
      for (var i = 0; i < Nd; i++) {
        var x = data[i][0], y = data[i][1], pr = p0 + p1 * x;
        gRes.line(bX(x), bY(y), bX(x), bY(pr))
          .stroke({ color: '#7d8688', width: 1.8, opacity: 0.85 });
      }
    }
    lossText.text('L[φ] = ' + loss(p0, p1).toFixed(3));
  }

  function setParams(p0, p1) {
    st.p0 = Math.max(0, Math.min(2, p0));
    st.p1 = Math.max(-1, Math.min(1, p1));
    st.step = -1;
    for (var k = 0; k < iter.length; k++) {
      if (Math.abs(st.p0 - iter[k][0]) < 0.006 && Math.abs(st.p1 - iter[k][1]) < 0.006) { st.step = k; break; }
    }
    syncUI(); render();
  }
  function setStep(k) { setParams(iter[k][0], iter[k][1]); }

  window.update_intercept = function (v) { setParams(v, st.p1); };
  window.update_slope = function (v) { setParams(st.p0, v); };
  window.trigger_descentStep = function () {
    var next = (st.step < 0) ? 0 : (st.step + 1) % iter.length;
    setStep(next);
  };
  window.toggle_showResiduals = function (on) { showRes = !!on; render(); };

  /* ── dragging in parameter space ────────────────────────────── */
  var dragging = false;
  function toWorld(evt) {
    var pt = draw.node.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    var p = pt.matrixTransform(draw.node.getScreenCTM().inverse());
    return { p0: (p.x - A.x) / A.s * 2, p1: (p.y - A.y) / A.s * 2 - 1 };
  }
  function dragTo(evt) { var w = toWorld(evt); setParams(w.p0, w.p1); }

  overlay.on('mousedown', function (e) { dragging = true; dragTo(e); e.preventDefault(); });
  overlay.on('mousemove', function (e) {
    var w = toWorld(e);
    var q0 = Math.max(0, Math.min(2, w.p0)), q1 = Math.max(-1, Math.min(1, w.p1));
    showTooltip('φ₀=' + q0.toFixed(2) + ', φ₁=' + q1.toFixed(2) + '  →  L[φ]=' + loss(q0, q1).toFixed(3), e);
    if (dragging) dragTo(e);
  });
  overlay.on('mouseleave', hideTooltip);
  overlay.on('click', function () {
    showPopup('Parameter space',
      'Each location in this square is one pair (φ₀, φ₁), i.e. one candidate line. Colour and contours show its loss: dark is low loss, pale is high. Training is the search for the deepest point of this bowl.');
  });
  curMarker.on('mousedown', function (e) { dragging = true; dragTo(e); e.preventDefault(); });
  curMarker.on('mousemove', function (e) {
    showTooltip('Current model: φ₀=' + st.p0.toFixed(2) + ', φ₁=' + st.p1.toFixed(2) + '   L=' + loss(st.p0, st.p1).toFixed(3), e);
  }).on('mouseleave', hideTooltip);
  window.addEventListener('mousemove', function (e) { if (dragging) dragTo(e); });
  window.addEventListener('mouseup', function () { dragging = false; });

  /* ── demo step player ───────────────────────────────────────── */
  var steps = [
    {
      t: 'A bad guess',
      n: 'We start at point 0: a small intercept and a slightly negative slope. On the loss surface the marker sits in a dark, high-loss region; in the data panel the corresponding line is flat and far below the points.',
      s: { descentStep: '0', intercept: 0.12, slope: -0.13, showResiduals: 'hidden' }
    },
    {
      t: 'Loss = summed squared errors',
      n: 'Turn on the residuals. Each grey stub is one data point\u2019s error; the height of the loss surface at the marker is just the sum of their squares.',
      s: { descentStep: '0', showResiduals: 'shown' }
    },
    {
      t: 'Move the intercept only',
      n: 'Push φ₀ to the right. The marker travels horizontally across the contours and the line rises bodily without tilting — the loss drops, but only partway.',
      s: { intercept: 0.85, slope: -0.13, showResiduals: 'shown' }
    },
    {
      t: 'Move the slope only',
      n: 'Now increase φ₁. The marker drops vertically into the basin and the line rotates to match the trend of the data.',
      s: { intercept: 0.85, slope: 0.5, showResiduals: 'shown' }
    },
    {
      t: 'Let gradient descent do it',
      n: 'Step the optimizer. Each click takes one downhill step from 0 to 4; the steps shorten as the surface flattens near the minimum, and the fitted lines fan up toward the data.',
